// Ícono elegido por pieza: '' = automático (foto o dibujo por categoría), 'photo:N' = una de sus fotos, o una clave de la galería.
function iconArt(key,a={}){const ic=ICON_BY_KEY[key];if(!ic)return equipment(a);if(ic.full)return equipment({},true);if(ic.cat)return equipment({...a,category:ic.cat});return `<svg class="equipment-svg" viewBox="0 0 250 170" aria-hidden="true">${ic.art}</svg>`;}
function assetVisual(a){const m=/^photo:(\d)$/.exec(a.icon||''),ph=m?a.photos?.[+m[1]]:(!a.icon||!ICON_BY_KEY[a.icon])?a.photos?.[0]:'';
  return ph?{photo:ph,html:`<img src="${ph}" alt="" loading="lazy">`}:{photo:'',html:a.icon&&ICON_BY_KEY[a.icon]?iconArt(a.icon,a):equipment(a)};}
function showIconPicker(id){const a=byId(id);if(!a)return;const cur=a.icon||'';
  const opt=(val,label,inner)=>`<button type="button" class="icon-opt${cur===val?' active':''}" data-action="asset-icon-pick" data-id="${esc(id)}" data-icon="${esc(val)}" aria-pressed="${cur===val}"><div class="icon-opt-art">${inner}</div><span>${esc(label)}</span></button>`;
  const own=[opt('','Automático',a.photos?.length?`<img src="${a.photos[0]}" alt="">`:equipment(a)),...(a.photos||[]).map((p,i)=>opt('photo:'+i,'Foto '+(i+1),`<img src="${p}" alt="">`))].join('');
  const groups=[...new Set(EQUIPMENT_ICONS.map(i=>i.group))];
  openModal(`Ícono · ${a.name}`,`<div class="modal-body"><p class="muted">Elige cómo se ve esta pieza en las listas y en su ficha. «Automático» usa su primera foto o el dibujo de su categoría.</p><h3 class="icon-group">De esta pieza</h3><div class="icon-grid">${own}</div>${groups.map(g=>`<h3 class="icon-group">${esc(g)}</h3><div class="icon-grid">${EQUIPMENT_ICONS.filter(i=>i.group===g).map(i=>opt(i.key,i.label,iconArt(i.key,a))).join('')}</div>`).join('')}</div><div class="modal-foot">${btn('Cerrar','close')}</div>`,{wide:true});}
const thumb = a => {const v=assetVisual(a);return `<div class="thumb${v.photo?' has-photo':''}">${v.html}</div>`;};
function toast(text, error=false) {
  const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.innerHTML=`${icon(error?'info':'check')}<span>${esc(text)}</span>`;$('#toasts').append(node);setTimeout(()=>node.remove(),6500);
}
async function api(action, payload=null, headers={}) {
  if(typeof window.__KB_DEMO_API__==='function')return window.__KB_DEMO_API__(action,payload);
  const res=await fetch(`api.php?action=${encodeURIComponent(action)}`,{credentials:'same-origin',cache:'no-store',method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-CSRF-Token':csrf||'',...headers}:headers,body:payload?JSON.stringify(payload):undefined});
  let data;try{data=await res.json();}catch{throw new Error('El servidor no respondió con datos válidos.');}
  if(!res.ok && !data.requiresLogin && !data.configurationRequired){if(res.status===409 && data.state){state=data.state;render();}throw new Error(data.error||'No se pudo completar la operación.');}
  return data;
}
function saveDemo() {if(mode==='demo'){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{toast('No hay espacio para guardar. Exporta una copia desde Ajustes.',true);}}}
async function command(cmd, success, after=()=>{}) {
  if(busy)return;busy=true;document.body.classList.add('busy');
  try { const data=await api('command',{command:cmd,revision:state.revision,...(mode==='demo'?{state}:{})});state=data.state;saveDemo();selected=new Set([...selected].filter(id=>available(byId(id)||{})));closeModal(true);render();if(success)toast(success);after(); }
  catch(e){const error=$('.modal .form-error');if(error)error.textContent=e.message;else toast(e.message,true);}
  finally{busy=false;document.body.classList.remove('busy');}
}
async function bootstrap() {
  try {
    const data=await api('bootstrap');mode=data.mode;
    if(data.requiresLogin || data.needsSetup || data.configurationRequired){renderAuth(data);return;}
    user=data.user;csrf=data.csrf;state=data.state;loadCart();
    if(mode==='demo'){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY)||'null');if(saved?.version===1 && Array.isArray(saved.assets)&&Array.isArray(saved.kits)&&Array.isArray(saved.events)&&Array.isArray(saved.movements))state=saved;}catch{}}
    document.body.dataset.motion=localStorage.getItem('kb-motion')||'on';document.body.dataset.largeText=localStorage.getItem('kb-large-text')||'off';shell();render();guidedTour.offer();
  }catch(e){$('#app').innerHTML=`<div class="auth-screen"><div class="auth-card panel panel-pad"><h1>Bodega sin conexión</h1><p>${esc(e.message)}</p>${btn('Volver a intentar','retry','','primary')}</div></div>`;}
}
function renderAuth(data) {
  const setup=data.needsSetup;
  $('#app').innerHTML=`<div class="auth-screen"><div class="auth-card"><div class="brand"><div class="brand-mark">K</div><div><div class="brand-name">KLANDESTINO</div><span class="brand-sub">BACKLINE MANAGER</span></div></div><div class="panel"><div class="eyebrow">Control de bodega</div><h1 class="gap">${setup?'Configura tu bodega':'Acceso del equipo'}</h1><p>${data.configurationRequired?esc(data.error):setup?'Crea el administrador de la instalación. Necesitas la clave definida en el servidor.':'Ingresa para coordinar inventario, salidas y retornos.'}</p>${data.configurationRequired?'':`<form data-form="${setup?'setup':'login'}">${setup?'<label>Nombre del administrador<input name="name" required maxlength="120" autocomplete="name"></label><label>Clave de instalación<input name="setupKey" type="password" required autocomplete="off"></label>':''}<label>Correo<input name="email" type="email" required maxlength="190" autocomplete="username"></label><label>Contraseña<input name="password" type="password" required ${setup?'minlength="12"':''} maxlength="128" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<label class="check-label"><input name="seedDemo" type="checkbox">Cargar el inventario oficial 2026 (sin eventos)</label>':''}<div class="form-error" role="alert"></div><button class="btn primary">${setup?'Crear administrador':'Ingresar'} ${icon('arrow')}</button></form>`}</div><div class="footer-note">KLANDESTINO INC SPA · BACKLINE / KREW / PRODUCCIÓN</div></div></div>`;
}
// Bodegas propias, solo por letra: la app no guarda sus direcciones.
