  if(wiz.step==='confirm'){const e=eventById(wiz.eventId),byGroup=KIT_GROUPS.map(([g,label])=>[label,picks.filter(a=>partGroup(a)===g)]).filter(([,l])=>l.length);body=`<h3 class="wiz-q">¿Reservamos esto?</h3><div class="wiz-summary"><div><small>Evento</small><strong>${esc(e?.name||'')}</strong><span>${esc(e?.place||'')}</span></div><div><small>Piezas</small><strong>${picks.length} de ${kitParts(wiz.kitId).length}</strong><span>${kitParts(wiz.kitId).length-picks.length} quedan en bodega</span></div></div><ul class="wiz-list">${byGroup.map(([label,l])=>`<li><strong>${label} · ${l.length}</strong><span>${l.map(a=>esc(a.name)).join(', ')}</span></li>`).join('')}</ul>`;next=btn(`${icon('check')} Reservar ${picks.length} piezas`,'wiz-confirm','','primary');}
  const back=n>1?btn(`${icon('back')} Atrás`,'wiz-back','','ghost'):btn('Cancelar','close','','ghost');
