function photoStrip(){return assetPhotos.map((p,i)=>`<figure class="photo-tile"><img src="${p}" alt="Foto ${i+1}"><button type="button" class="photo-del" data-action="asset-photo-del" data-i="${i}" aria-label="Quitar foto ${i+1}">${icon('close')}</button></figure>`).join('')+(assetPhotos.length<MAX_PHOTOS?`<label class="photo-add">${icon('plus')}<span>${assetPhotos.length?'Otra foto':'Agregar foto'}</span><input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple data-asset-photo></label>`:'');}
async function compressAssetPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw new Error('Usa fotos JPG, PNG o WebP de hasta 15 MB.');const img=await createImageBitmap(file),scale=Math.min(1,640/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close();let q=.72,out=c.toDataURL('image/jpeg',q);while(out.length>85000&&q>.25){q-=.08;out=c.toDataURL('image/jpeg',q);}if(out.length>=90000)throw new Error('Una foto quedó muy pesada; prueba otra.');return out;}
let eventPoster='';const DEFAULT_POSTER='assets/poster-default.svg';const posterSrc=e=>e?.poster||DEFAULT_POSTER;
const posterField=()=>`<div class="span2 poster-field"><span class="field-label">Afiche del evento <small>(opcional)</small></span><div id="posterSlot">${posterSlot()}</div></div>`;
function posterSlot(){return eventPoster?`<figure class="poster-tile"><img src="${eventPoster}" alt="Afiche del evento"><button type="button" class="photo-del" data-action="poster-del" aria-label="Quitar afiche">${icon('close')}</button></figure>`:`<label class="photo-add poster-add">${icon('plus')}<span>Agregar afiche</span><input type="file" name="posterFile" accept="image/jpeg,image/png,image/webp" data-event-poster></label>`;}
async function compressPoster(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20000000)throw new Error('Usa un afiche JPG, PNG o WebP de hasta 20 MB.');const img=await createImageBitmap(file),scale=Math.min(1,1100/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(img,0,0,c.width,c.height);img.close();let q=.8,out=c.toDataURL('image/jpeg',q);while(out.length>240000&&q>.3){q-=.08;out=c.toDataURL('image/jpeg',q);}if(out.length>=260000)throw new Error('El afiche quedó muy pesado; prueba con otra imagen.');return out;}
async function setEventPoster(file){if(!file)return;try{eventPoster=await compressPoster(file);}catch(e){toast(e.message,true);}const s=$('#posterSlot');if(s)s.innerHTML=posterSlot();}
function showPoster(id){const e=eventById(id);if(!e?.poster)return;openModal(`Afiche · ${e.name}`,`<div class="modal-body"><img class="poster-full" src="${e.poster}" alt="Afiche de ${esc(e.name)}"></div><div class="modal-foot">${btn('Cerrar','close')}</div>`);}
