async function addAssetPhotos(files){try{for(const f of [...files].slice(0,MAX_PHOTOS-assetPhotos.length))assetPhotos.push(await compressAssetPhoto(f));}catch(e){toast(e.message,true);}const s=$('#assetPhotoStrip');if(s)s.innerHTML=photoStrip();}
const codePart=(t,n)=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'').slice(0,n);
const CAT_CODE={Tambores:'DRM',Platillos:'CYM',Fierros:'HW',Accesorios:'ACC',Gabinetes:'CAB',Cabezales:'HEAD',Micrófonos:'MIC',Cables:'CBL',Cases:'CASE'};
function suggestCode({name='',category='',brand='',model=''}){const norm=t=>String(t||'').trim().toLowerCase();const twin=state.assets.find(a=>brand&&model&&norm(a.brand)===norm(brand)&&norm(a.model)===norm(model)&&/-\d{2,4}$/.test(a.code));let base;if(twin)base=twin.code.replace(/-\d{2,4}$/,'');else{const b=codePart(brand,3)||CAT_CODE[category]||'KB',m=codePart(String(model).split(/[\s·,/]+/)[0],8)||codePart(String(name).split(/\s+/).find(w=>/\d/.test(w))||String(name).split(/\s+/)[0],6);base=m&&m!==b?`${b}-${m}`:b;}const used=new Set([...state.assets.flatMap(a=>[a.code,a.id]),...state.kits.map(k=>k.id)].map(x=>String(x).toUpperCase()));let n=1;while(used.has(`${base}-${String(n).padStart(3,'0')}`))n++;return {code:`${base}-${String(n).padStart(3,'0')}`,twin};}
function fillSuggestedCode(force=false){const f=$('form[data-form="asset"]');if(!f||(codeTouched&&!force))return;const v=Object.fromEntries(new FormData(f));if(!force&&!v.brand&&!v.model&&!v.name)return;const {code,twin}=suggestCode(v);f.code.value=code;if(force)codeTouched=false;const h=$('#codeHint');if(h)h.textContent=twin?`Sigue la serie de «${twin.name}». Puedes cambiarlo.`:'Código sugerido. Puedes cambiarlo antes de guardar.';}
function showTransfer(ids,context=''){const list=ids.map(byId).filter(Boolean),free=list.filter(available),blocked=list.length-free.length;if(!free.length){toast('No hay piezas disponibles en bodega para trasladar.',true);return;}transferIds=free.map(a=>a.id);const from=[...new Set(free.map(a=>a.location))];const target=WAREHOUSES.find(w=>!from.includes(w))||WAREHOUSES[0];
openModal('Trasladar entre bodegas',`<form data-form="transfer"><div class="modal-body"><p><strong>${free.length} ${free.length===1?'pieza':'piezas'}</strong>${context?` de ${esc(context)}`:''} · hoy en ${esc(from.join(' y '))}.</p>${blocked?`<div class="notice gap">${icon('info')}<span>${blocked} ${blocked===1?'pieza no está':'piezas no están'} en bodega (reservadas, fuera o en taller) y se quedan donde están.</span></div>`:''}<fieldset class="warehouse-choice gap"><legend>Llevar a</legend>${WAREHOUSES.map(w=>`<label class="check-label"><input type="radio" name="warehouse" value="${w}" ${w===target?'checked':''} required>${w}</label>`).join('')}</fieldset><label class="gap">Nota (opcional)<input name="note" maxlength="500" placeholder="Ej. Conteo de inventario"></label><p class="muted gap">Al volver de un evento o del taller, cada pieza regresa a su nueva bodega.</p><div class="form-error gap" role="alert"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">${icon('truck')} Trasladar</button></div></form>`);}
