const LAB_SIZES=[['s','Pequeña','Cables, micrófonos y accesorios'],['m','Mediana','Tambores, atriles y cases'],['l','Grande','Gabinetes y kits']];
function labelGroups(){const groups=[];for(const k of state.kits){const parts=kitParts(k.id);const items=[{id:k.id,name:'QR general del kit',tag:'Kit',isKit:true}];for(const [g,label] of KIT_GROUPS)parts.filter(a=>partGroup(a)===g).forEach(a=>items.push({id:a.id,name:a.name,tag:label}));groups.push({id:'kit:'+k.id,title:k.name,sub:`Kit · ${parts.length} piezas + QR general`,items});}
  const loose=state.assets.filter(a=>!a.kitId||!kitById(a.kitId));for(const c of [...new Set(loose.map(a=>a.category))].sort((a,b)=>a.localeCompare(b,'es')))groups.push({id:'cat:'+c,title:c,sub:'Equipos sueltos',items:loose.filter(a=>a.category===c).sort((a,b)=>a.code.localeCompare(b.code)).map(a=>({id:a.id,name:a.name,tag:''}))});return groups;}
